import { createMoney, add, subtract } from "./src/money.ts";

// Edge case: case sensitivity - EUR vs Eur should be normalized by createMoney
const eur1 = createMoney(10, "EUR");
const eur2 = createMoney(5, "eur");  // normalized to EUR
const result1 = add(eur1, eur2);
console.log("Same currency (case-normalized):", result1);

// Edge case: same currency subtraction
const result2 = subtract(createMoney(100, "JPY"), createMoney(30, "JPY"));
console.log("Same currency subtraction:", result2);

// Edge case: third currency
try {
  add(createMoney(10, "GBP"), createMoney(5, "JPY"));
  console.log("BUG: GBP + JPY should have thrown");
} catch (e) {
  console.log("OK: GBP + JPY threw:", (e as Error).message);
}

// Edge case: negative amounts (still same currency)
const result3 = add(createMoney(10, "USD"), createMoney(-3, "USD"));
console.log("Negative amount same currency:", result3);

// Edge case: zero amount
const result4 = add(createMoney(10, "USD"), createMoney(0, "USD"));
console.log("Zero amount same currency:", result4);

