import { createMoney, add, subtract } from "./src/money.ts";

const usd10 = createMoney(10, "USD");
const eur5 = createMoney(5, "EUR");

// This should throw a Currency mismatch error but currently succeeds
try {
  const result = add(usd10, eur5);
  console.log("BUG: add(USD, EUR) succeeded:", result);
  console.log("Result:", result.amount, result.currency);
} catch (e) {
  console.log("OK: add(USD, EUR) threw:", (e as Error).message);
}

// Same for subtract
try {
  const result = subtract(usd10, eur5);
  console.log("BUG: subtract(USD, EUR) succeeded:", result);
  console.log("Result:", result.amount, result.currency);
} catch (e) {
  console.log("OK: subtract(USD, EUR) threw:", (e as Error).message);
}

// Same currency should work
try {
  const result = add(usd10, createMoney(5, "USD"));
  console.log("OK: add(USD, USD) succeeded:", result);
} catch (e) {
  console.log("BUG: add(USD, USD) threw:", (e as Error).message);
}

